<?php if(!empty($registryStats)): ?><dl class="registry-stats" aria-label="Student ID registry statistics"><?php foreach(['total'=>'Total approved Student IDs','active'=>'Active eligible IDs','claimed'=>'Claimed IDs','accounts'=>'Registered student accounts','unclaimed'=>'Unclaimed IDs','rejected'=>'Rejected registrations','recent'=>'IDs imported this week'] as $registryKey=>$registryLabel): ?><div><dt><?= htmlspecialchars($registryLabel,ENT_QUOTES,'UTF-8') ?></dt><dd data-stat="<?= $registryKey ?>"><?= (int)$registryStats[$registryKey] ?></dd></div><?php endforeach; ?></dl><?php endif; ?>
